#include "engine/platform/UserStorage.hpp"
#include <fstream>
namespace kb::platform { UserStorage::UserStorage(std::filesystem::path root,std::uintmax_t quotaBytes):root_(std::move(root)),quotaBytes_(quotaBytes){std::filesystem::create_directories(root_);} std::filesystem::path UserStorage::PathFor(std::string_view key) const{return IsSandboxStorageKey(key)?root_/std::filesystem::path{key}:std::filesystem::path{};} std::uintmax_t UserStorage::Usage() const{std::uintmax_t total=0;std::error_code e;for(std::filesystem::recursive_directory_iterator i(root_,e),end;i!=end&&!e;i.increment(e))if(i->is_regular_file(e))total+=i->file_size(e);return total;} bool UserStorage::Write(std::string_view key,std::string_view data){const auto path=PathFor(key);if(path.empty()||data.size()>quotaBytes_)return false;std::error_code e;const auto old=std::filesystem::exists(path,e)?std::filesystem::file_size(path,e):0U;if(Usage()-old+data.size()>quotaBytes_)return false;std::filesystem::create_directories(path.parent_path(),e);const auto temp=path.string()+".tmp";{std::ofstream out(temp,std::ios::binary|std::ios::trunc);if(!out)return false;out.write(data.data(),static_cast<std::streamsize>(data.size()));if(!out)return false;}std::filesystem::rename(temp,path,e);if(e){std::filesystem::remove(path,e);e.clear();std::filesystem::rename(temp,path,e);}return !e;} std::optional<std::string> UserStorage::Read(std::string_view key) const{const auto path=PathFor(key);std::ifstream in(path,std::ios::binary);if(!in)return std::nullopt;return std::string{std::istreambuf_iterator<char>{in},{}};} bool UserStorage::Delete(std::string_view key){std::error_code e;return std::filesystem::remove(PathFor(key),e);} std::vector<std::string> UserStorage::List() const{std::vector<std::string> result;std::error_code e;for(std::filesystem::recursive_directory_iterator i(root_,e),end;i!=end&&!e;i.increment(e))if(i->is_regular_file(e))result.push_back(std::filesystem::relative(i->path(),root_,e).generic_string());return result;} std::future<bool> UserStorage::WriteAsync(std::string key,std::string data){return std::async(std::launch::async,[this,key=std::move(key),data=std::move(data)]{return Write(key,data);});} }
